import SwiftUI

/// Line icons drawn from the design file (24 by 24 grid). Generated by svg2swift.py from `docs/design/build_design.py`.
enum DSIcon: CaseIterable {
    case back, house, sliders, bell, clock, check, clip, mic, send, x, warn, stop, photo, doc, link, camera, lock, speaker, mark, plus
}

struct DSIconShape: Shape {
    let icon: DSIcon

    func path(in rect: CGRect) -> Path {
        let k = min(rect.width, rect.height) / 24
        func P(_ x: CGFloat, _ y: CGFloat) -> CGPoint { CGPoint(x: rect.minX + x * k, y: rect.minY + y * k) }
        var p = Path()
        switch icon {
        case .back:
            p.move(to: P(15, 5))
            p.addLine(to: P(8, 12))
            p.addLine(to: P(15, 19))
        case .house:
            p.move(to: P(4, 11))
            p.addLine(to: P(12, 4))
            p.addLine(to: P(20, 11))
            p.move(to: P(6, 10))
            p.addLine(to: P(6, 20))
            p.addLine(to: P(18, 20))
            p.addLine(to: P(18, 10))
        case .sliders:
            p.move(to: P(4, 7))
            p.addLine(to: P(14, 7))
            p.move(to: P(18, 7))
            p.addLine(to: P(20, 7))
            p.move(to: P(4, 17))
            p.addLine(to: P(6, 17))
            p.move(to: P(10, 17))
            p.addLine(to: P(20, 17))
            p.addEllipse(in: CGRect(x: rect.minX + 14*k, y: rect.minY + 5*k, width: 4*k, height: 4*k))
            p.addEllipse(in: CGRect(x: rect.minX + 6*k, y: rect.minY + 15*k, width: 4*k, height: 4*k))
        case .bell:
            p.move(to: P(6, 16))
            p.addLine(to: P(6, 11))
            p.addCurve(to: P(12, 5), control1: P(6, 7.6863), control2: P(8.6863, 5))
            p.addCurve(to: P(18, 11), control1: P(15.3137, 5), control2: P(18, 7.6863))
            p.addLine(to: P(18, 16))
            p.addLine(to: P(19.5, 18))
            p.addLine(to: P(4.5, 18))
            p.closeSubpath()
            p.move(to: P(10, 20.5))
            p.addCurve(to: P(12, 22.5), control1: P(10, 21.6046), control2: P(10.8954, 22.5))
            p.addCurve(to: P(14, 20.5), control1: P(13.1046, 22.5), control2: P(14, 21.6046))
        case .clock:
            p.addEllipse(in: CGRect(x: rect.minX + 3*k, y: rect.minY + 3*k, width: 18*k, height: 18*k))
            p.move(to: P(12, 7.5))
            p.addLine(to: P(12, 12))
            p.addLine(to: P(15, 14))
        case .check:
            p.addEllipse(in: CGRect(x: rect.minX + 3*k, y: rect.minY + 3*k, width: 18*k, height: 18*k))
            p.move(to: P(8, 12.5))
            p.addLine(to: P(11, 15.5))
            p.addLine(to: P(16, 9.5))
        case .clip:
            p.move(to: P(20, 11.5))
            p.addLine(to: P(12, 19.5))
            p.addCurve(to: P(5.4645, 19.0355), control1: P(10.0094, 20.993), control2: P(7.2239, 20.795))
            p.addCurve(to: P(5, 12.5), control1: P(3.705, 17.2761), control2: P(3.507, 14.4906))
            p.addLine(to: P(13.5, 4))
            p.addCurve(to: P(18.2, 4), control1: P(14.7979, 2.7021), control2: P(16.9021, 2.7021))
            p.addCurve(to: P(18.2, 8.7), control1: P(19.4979, 5.2979), control2: P(19.4979, 7.4021))
            p.addLine(to: P(9.7, 17.2))
            p.addCurve(to: P(7.3686, 17.1314), control1: P(9.0272, 17.7979), control2: P(8.0051, 17.7678))
            p.addCurve(to: P(7.3, 14.8), control1: P(6.7322, 16.4949), control2: P(6.7021, 15.4728))
            p.addLine(to: P(14.8, 7.3))
        case .mic:
            p.addRoundedRect(in: CGRect(x: rect.minX + 9*k, y: rect.minY + 3*k, width: 6*k, height: 12*k), cornerSize: CGSize(width: 3*k, height: 3*k))
            p.move(to: P(5, 11))
            p.addCurve(to: P(12, 18), control1: P(5, 14.866), control2: P(8.134, 18))
            p.addCurve(to: P(19, 11), control1: P(15.866, 18), control2: P(19, 14.866))
            p.move(to: P(12, 18))
            p.addLine(to: P(12, 21))
        case .send:
            p.move(to: P(12, 19))
            p.addLine(to: P(12, 5))
            p.move(to: P(6, 11))
            p.addLine(to: P(12, 5))
            p.addLine(to: P(18, 11))
        case .x:
            p.move(to: P(6, 6))
            p.addLine(to: P(18, 18))
            p.move(to: P(18, 6))
            p.addLine(to: P(6, 18))
        case .warn:
            p.move(to: P(12, 4))
            p.addLine(to: P(21, 20))
            p.addLine(to: P(3, 20))
            p.closeSubpath()
            p.move(to: P(12, 10))
            p.addLine(to: P(12, 14))
            p.move(to: P(12, 17))
            p.addLine(to: P(12, 17.5))
        case .stop:
            p.addRoundedRect(in: CGRect(x: rect.minX + 7*k, y: rect.minY + 7*k, width: 10*k, height: 10*k), cornerSize: CGSize(width: 2*k, height: 2*k))
        case .photo:
            p.addRoundedRect(in: CGRect(x: rect.minX + 4*k, y: rect.minY + 5*k, width: 16*k, height: 14*k), cornerSize: CGSize(width: 2*k, height: 2*k))
            p.addEllipse(in: CGRect(x: rect.minX + 7.5*k, y: rect.minY + 8.5*k, width: 3*k, height: 3*k))
            p.move(to: P(4, 16))
            p.addLine(to: P(9, 12))
            p.addLine(to: P(13, 15))
            p.addLine(to: P(16, 13))
            p.addLine(to: P(20, 16))
        case .doc:
            p.move(to: P(7, 3))
            p.addLine(to: P(14, 3))
            p.addLine(to: P(19, 8))
            p.addLine(to: P(19, 21))
            p.addLine(to: P(7, 21))
            p.closeSubpath()
            p.move(to: P(14, 3))
            p.addLine(to: P(14, 8))
            p.addLine(to: P(19, 8))
        case .link:
            p.move(to: P(10, 14))
            p.addCurve(to: P(12.85, 15.1933), control1: P(10.7518, 14.7634), control2: P(11.7785, 15.1933))
            p.addCurve(to: P(15.7, 14), control1: P(13.9215, 15.1933), control2: P(14.9482, 14.7634))
            p.addLine(to: P(18.7, 11))
            p.addCurve(to: P(18.7, 5.3), control1: P(20.274, 9.426), control2: P(20.274, 6.874))
            p.addCurve(to: P(13, 5.3), control1: P(17.126, 3.726), control2: P(14.574, 3.726))
            p.addLine(to: P(12, 6.3))
            p.move(to: P(14, 10))
            p.addCurve(to: P(11.15, 8.8067), control1: P(13.2482, 9.2366), control2: P(12.2215, 8.8067))
            p.addCurve(to: P(8.3, 10), control1: P(10.0785, 8.8067), control2: P(9.0518, 9.2366))
            p.addLine(to: P(5.3, 13))
            p.addCurve(to: P(5.3, 18.7), control1: P(3.726, 14.574), control2: P(3.726, 17.126))
            p.addCurve(to: P(11, 18.7), control1: P(6.874, 20.274), control2: P(9.426, 20.274))
            p.addLine(to: P(12, 17.7))
        case .camera:
            p.addRoundedRect(in: CGRect(x: rect.minX + 3*k, y: rect.minY + 7*k, width: 18*k, height: 13*k), cornerSize: CGSize(width: 2*k, height: 2*k))
            p.addEllipse(in: CGRect(x: rect.minX + 8.5*k, y: rect.minY + 9.5*k, width: 7*k, height: 7*k))
            p.move(to: P(8, 7))
            p.addLine(to: P(9.5, 4))
            p.addLine(to: P(14.5, 4))
            p.addLine(to: P(16, 7))
        case .lock:
            p.addRoundedRect(in: CGRect(x: rect.minX + 5*k, y: rect.minY + 10*k, width: 14*k, height: 10*k), cornerSize: CGSize(width: 2*k, height: 2*k))
            p.move(to: P(8, 10))
            p.addLine(to: P(8, 7))
            p.addCurve(to: P(12, 3), control1: P(8, 4.7909), control2: P(9.7909, 3))
            p.addCurve(to: P(16, 7), control1: P(14.2091, 3), control2: P(16, 4.7909))
            p.addLine(to: P(16, 10))
        case .speaker:
            p.addRoundedRect(in: CGRect(x: rect.minX + 6*k, y: rect.minY + 3*k, width: 12*k, height: 18*k), cornerSize: CGSize(width: 4*k, height: 4*k))
            p.addEllipse(in: CGRect(x: rect.minX + 9*k, y: rect.minY + 11*k, width: 6*k, height: 6*k))
            p.addEllipse(in: CGRect(x: rect.minX + 11*k, y: rect.minY + 6.5*k, width: 2*k, height: 2*k))
        case .plus:
            p.move(to: P(12, 5))
            p.addLine(to: P(12, 19))
            p.move(to: P(5, 12))
            p.addLine(to: P(19, 12))
        case .mark:
            p.move(to: P(6, 19))
            p.addLine(to: P(12, 5))
            p.addLine(to: P(18, 19))
            p.addEllipse(in: CGRect(x: rect.minX + 10.8*k, y: rect.minY + 13.8*k, width: 2.4*k, height: 2.4*k))
        }
        return p
    }
}
